import math

good_numbers = set()
count = 0
search_limit = 100  # Start with a moderate limit for x and y

# Iterate over possible pairs (x, y) with x < y
for x in range(2, search_limit + 1):
    for y in range(x + 1, search_limit + 1):
        if math.gcd(x, y) > 1:
            m = x**2 + y**2
            if m not in good_numbers:
                good_numbers.add(m)

# Convert to a sorted list
sorted_good_numbers = sorted(list(good_numbers))

print(f"Total unique good numbers found up to limit {search_limit}: {len(sorted_good_numbers)}")

if len(sorted_good_numbers) >= 20:
    print(f"The 20th smallest good number is: {sorted_good_numbers[19]}")
else:
    print(f"Need to increase search limit. Found only {len(sorted_good_numbers)} numbers.")
